define(['jquery', 'uiComponent', 'Magento_Customer/js/customer-data'], function($, Component, customerData) {
    'use strict';
    return Component.extend({
        defaults: {
            imports: {
                color_settings: 'index = ammenu_wrapper:color_settings',
                isOpen: 'index = ammenu_hamburger_toggle:isOpen'
            }
        },
        initObservable: function() {
            this._super().observe({
                activeTab: 0,
                isOpen: false,
                tabsList: [{
                    title: $.mage.__('Menu')
                }, {
                    title: $.mage.__('Account')
                }]
            });
            return this;
        },
        isCustomerLogin: function() {
            var customer = customerData.get('customer')();
            if (customer && customer.firstname) {
                return 'Hi ' + customer.firstname + ' ' + (customer.lastname || '');
            }
            return $.mage.__('Login / Register');
        }
    });
});